// lib/api/client.ts - Next.js API Client for Flask Backend

const API_BASE = process.env.NEXT_PUBLIC_API_URL || 'https://stock-dashboard-backend-634072894074.us-west4.run.app';

export interface AssetData {
  symbol: string;
  price: number;
  change: number;
  volume: number;
  high: number;
  low: number;
}

export interface AssetDetail {
  symbol: string;
  asset_type: string;
  timeframe: string;
  current_price: number;
  change_pct: number;
  high: number;
  low: number;
  volume: number;
  technical_indicators: {
    rsi: number | null;
    macd: number | null;
    macd_signal: number | null;
    macd_histogram: number | null;
    bollinger_upper: number | null;
    bollinger_mid: number | null;
    bollinger_lower: number | null;
    atr: number | null;
  };
  ai_analysis: string | null;
  data: any[];
  timestamp: string;
}

export interface MarketOverview {
  markets: {
    name: string;
    symbol: string;
    price: number;
    change: number;
    high: number;
    low: number;
  }[];
  timestamp: string;
}

export interface BatchAnalysisRequest {
  assets: {
    symbol: string;
    type: string;
    timeframe?: string;
  }[];
}

export interface HybridChartRequest {
  symbol: string;
  asset_type: string;
  timeframe?: string;
  include_ai?: boolean;
}

export const apiClient = {
  // Health check
  async healthCheck() {
    const response = await fetch(`${API_BASE}/api/health`);
    return response.json();
  },

  // Get all stocks
  async getStocks(): Promise<{ data: AssetData[]; count: number }> {
    const response = await fetch(`${API_BASE}/api/stocks`);
    if (!response.ok) throw new Error('Failed to fetch stocks');
    return response.json();
  },

  // Get NASDAQ stocks
  async getNasdaq(): Promise<{ data: AssetData[]; count: number }> {
    const response = await fetch(`${API_BASE}/api/nasdaq`);
    if (!response.ok) throw new Error('Failed to fetch NASDAQ');
    return response.json();
  },

  // Get cryptocurrencies
  async getCrypto(): Promise<{ data: AssetData[]; count: number }> {
    const response = await fetch(`${API_BASE}/api/crypto`);
    if (!response.ok) throw new Error('Failed to fetch crypto');
    return response.json();
  },

  // Get forex pairs
  async getForex(): Promise<{ data: AssetData[]; count: number }> {
    const response = await fetch(`${API_BASE}/api/forex`);
    if (!response.ok) throw new Error('Failed to fetch forex');
    return response.json();
  },

  // Get futures
  async getFutures(): Promise<{ data: AssetData[]; count: number }> {
    const response = await fetch(`${API_BASE}/api/futures`);
    if (!response.ok) throw new Error('Failed to fetch futures');
    return response.json();
  },

  // Get single asset detail
  async getAssetDetail(symbol: string, type: string = 'stock', timeframe: string = '3M', includeAI: boolean = true): Promise<AssetDetail> {
    const response = await fetch(
      `${API_BASE}/api/asset/${symbol}?type=${type}&timeframe=${timeframe}&ai=${includeAI}`
    );
    if (!response.ok) throw new Error(`Failed to fetch ${symbol}`);
    return response.json();
  },

  // Get market overview
  async getMarketOverview(): Promise<MarketOverview> {
    const response = await fetch(`${API_BASE}/api/market/overview`);
    if (!response.ok) throw new Error('Failed to fetch market overview');
    return response.json();
  },

  // Hybrid chart analysis
  async hybridChart(request: HybridChartRequest) {
    const response = await fetch(`${API_BASE}/api/chart/hybrid`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(request),
    });
    if (!response.ok) throw new Error('Failed to fetch hybrid chart');
    return response.json();
  },

  // Batch analysis
  async batchAnalysis(request: BatchAnalysisRequest) {
    const response = await fetch(`${API_BASE}/api/chart/batch`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(request),
    });
    if (!response.ok) throw new Error('Failed to fetch batch analysis');
    return response.json();
  },

  // Streaming analysis (Server-Sent Events)
  streamAnalysis(symbol: string, onMessage: (data: any) => void, onError: (error: any) => void) {
    const eventSource = new EventSource(`${API_BASE}/api/chart/stream/${symbol}`);
    
    eventSource.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        onMessage(data);
      } catch (e) {
        onError(e);
      }
    };
    
    eventSource.onerror = (error) => {
      onError(error);
      eventSource.close();
    };
    
    return eventSource;
  },
};
